        /// <summary>
        ///   Destroy the specified track.
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     If the track is currently playing, it will be stopped immediately, without
        ///     any fadeout. If there is a callback set through
        ///     MIX_SetTrackStoppedCallback(), it will <em>not</em> be called.
        ///   </para>
        ///   <para>
        ///     If the mixer is currently mixing in another thread, this will block until
        ///     it finishes. Destroying a track from the mixer thread itself (during a
        ///     callback) will cause it to be destroyed as soon as this iteration of the
        ///     mixer thread is not using it; in this scenario, destroying a track and then
        ///     making futher changes to it is considered undefined behavior.
        ///   </para>
        ///   <para>
        ///     Destroying a NULL MIX_Track is a legal no-op.
        ///   </para>
        ///   <para>
        ///     This is equivalent to Dispose(): it is a safe no-op on a default (null) handle and otherwise performs
        ///     the single native free. Because a handle is a copyable value type, it cannot invalidate its own copies
        ///     after the free, so calling this (or Dispose) more than once on the same handle value — or on separate
        ///     copies of it — frees the underlying native object more than once. Free each handle exactly once.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   It is safe to call this function from any thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL_mixer 3.0.0.
        /// </since>
        public void Destroy()
        {
            if (IsNull())
            {
                return;
            }
            SdlMixer.DestroyTrack(this);
        }

