        /// <exception cref="SdlException">The SDL call failed; the message carries the <c>SDL_GetError</c>
        ///   text.</exception>
        public void SetFrequencyRatio(float ratio) => SdlMixer.SetTrackFrequencyRatio(this, ratio);

