        /// <exception cref="SdlException">The SDL call failed; the message carries the <c>SDL_GetError</c>
        ///   text.</exception>
        public void SetRawIOStream(nint io, SdlAudioSpec* spec, bool closeio) =>
            SdlMixer.SetTrackRawIOStream(this, io, spec, closeio);

