        ///   text.</exception>
        public void Tag(string tag) => SdlMixer.TagTrack(this, tag);

        /// <summary>
        ///   Convert sample frames for a track's current format to milliseconds.
        /// </summary>
        /// <param name="frames">the track-specific sample frames to convert to milliseconds.</param>
        /// <returns>
        ///   Converted number of milliseconds, or -1 for errors/no input; call
        ///   SDL_GetError() for details.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This calculates time based on the track's current input format, which can
        ///     change when its input does, and also if that input changes formats
        ///     mid-stream (for example, if decoding a file that is two MP3s concatenated
        ///     together).
        ///   </para>
        ///   <para>
        ///     Sample frames are more precise than milliseconds, so out of necessity, this
        ///     function will approximate by rounding down to the closest full millisecond.
        ///   </para>
        ///   <para>
        ///     On various errors (MIX_Init() was not called, the track is NULL), this
        ///     returns -1. If the track has no input, this returns -1. If <c>frames</c> is &lt; 0,
        ///     this returns -1.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   It is safe to call this function from any thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL_mixer 3.0.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.TrackMSToFrames"/>
        public long FramesToMS(long frames) => SdlMixer.TrackFramesToMS(this, frames);

        /// <summary>
        ///   Convert milliseconds to sample frames for a track's current format.
        /// </summary>
        /// <param name="ms">the milliseconds to convert to track-specific sample frames.</param>
        /// <returns>
        ///   Converted number of sample frames, or -1 for errors/no input; call
        ///   SDL_GetError() for details.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This calculates time based on the track's current input format, which can
        ///     change when its input does, and also if that input changes formats
        ///     mid-stream (for example, if decoding a file that is two MP3s concatenated
        ///     together).
        ///   </para>
        ///   <para>
        ///     On various errors (MIX_Init() was not called, the track is NULL), this
        ///     returns -1. If the track has no input, this returns -1. If <c>ms</c> is &lt; 0,
        ///     this returns -1.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   It is safe to call this function from any thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL_mixer 3.0.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.TrackFramesToMS"/>
        public long MSToFrames(long ms) => SdlMixer.TrackMSToFrames(this, ms);

        /// <summary>
        ///   Query if a track is currently paused.
        /// </summary>
        /// <returns>true if paused, false otherwise.</returns>
        /// <remarks>
        ///   <para>
        ///     If this returns true, the track is not currently contributing to the
        ///     mixer's output but will when resumed (it's "paused"). It is not playing nor
        ///     stopped.
        ///   </para>
        ///   <para>
        ///     On various errors (MIX_Init() was not called, the track is NULL), this
        ///     returns false, but there is no mechanism to distinguish errors from
        ///     non-playing tracks.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   It is safe to call this function from any thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL_mixer 3.0.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.PlayTrack"/>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.PauseTrack"/>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.ResumeTrack"/>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.StopTrack"/>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.TrackPlaying"/>
        public bool Paused() => SdlMixer.TrackPaused(this);

        /// <summary>
        ///   Query if a track is currently playing.
        /// </summary>
        /// <returns>true if playing, false otherwise.</returns>
        /// <remarks>
        ///   <para>
        ///     If this returns true, the track is currently contributing to the mixer's
        ///     output (it's "playing"). It is not stopped nor paused.
        ///   </para>
        ///   <para>
        ///     On various errors (MIX_Init() was not called, the track is NULL), this
        ///     returns false, but there is no mechanism to distinguish errors from
        ///     non-playing tracks.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   It is safe to call this function from any thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL_mixer 3.0.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.PlayTrack"/>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.PauseTrack"/>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.ResumeTrack"/>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.StopTrack"/>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.TrackPaused"/>
        public bool Playing() => SdlMixer.TrackPlaying(this);

        /// <summary>
        ///   Remove an arbitrary tag from a track.
        /// </summary>
        /// <param name="tag">the tag to remove, or NULL to remove all current tags.</param>
        /// <remarks>
        ///   <para>
        ///     A tag can be any valid C string in UTF-8 encoding. It can be useful to
        ///     group tracks in various ways. For example, everything in-game might be
        ///     marked as "game", so when the user brings up the settings menu, the app can
        ///     pause all tracks involved in gameplay at once, but keep background music
        ///     and menu sound effects running.
        ///   </para>
        ///   <para>
        ///     It's legal to remove a tag that the track doesn't have; this function
        ///     doesn't report errors, so this simply does nothing.
        ///   </para>
        ///   <para>
        ///     Specifying a NULL tag will remove all tags on a track.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   It is safe to call this function from any thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL_mixer 3.0.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Mixer.SdlMixer.PInvoke.TagTrack"/>
        public void Untag(string tag) => SdlMixer.UntagTrack(this, tag);
    }
}
